by
  open M2
  -- Get the explicit matrix form of the (n+1)-th power
  have h_pow := OSO.comp_pow p q n
  -- Compute its determinant
  have h_det_form : det (pow (comp p q) (n + 1)) = (q : Int) * ((L p q (n + 2) : Int) * (L p q n : Int) - (L p q (n + 1) : Int) ^ 2) := by {
    rw [h_pow, det]
    ring
  }
  -- Get the known determinant value from det_comp_pow
  have h_det_val := OSO.det_comp_pow p q (n + 1)
  -- Equate the two expressions for the determinant
  have h_base_eq : (q : Int) * ((L p q (n + 2) : Int) * (L p q n : Int) - (L p q (n + 1) : Int) ^ 2) = (-(q : Int)) ^ (n + 1) := by {
    rw [← h_det_form, h_det_val]
  }
  -- Unpack the (n+1)-th power as product of n-th power and base
  have h_pow_succ : (-(q : Int)) ^ (n + 1) = (-(q : Int)) * (-(q : Int)) ^ n := by {
    simp [Int.pow_succ]
  }
  -- Rearrange the LHS: factor out -(q) by negating inside the parentheses
  have h_main : -(q : Int) * ((L p q (n + 1) : Int) ^ 2 - L p q (n + 2) * L p q n) = (-(q : Int)) * (-(q : Int)) ^ n := by {
    have h_lfactor : (q : Int) * ((L p q (n + 2) : Int) * (L p q n : Int) - (L p q (n + 1) : Int) ^ 2) = -(q : Int) * ((L p q (n + 1) : Int) ^ 2 - L p q (n + 2) * L p q n) := by {
      ring
    }
    rw [h_lfactor, ← h_base_eq, h_pow_succ]
  }
  -- Cancel the non-zero factor -(q) from both sides
  have h_result : (L p q (n + 1) : Int) ^ 2 - L p q (n + 2) * L p q n = (-(q : Int)) ^ n := by {
    have h_nonzero : -(q : Int) ≠ 0 := by {
      cases q <;> decide
    }
    exact mul_left_cancel₀ h_nonzero h_main
  }
  exact h_result

:= by
  open M2
  have h_det_form : det (pow (comp p q) (n + 1)) = (q : Int) * ((L p q (n + 2) : Int) * (L p q n : Int) - (L p q (n + 1) : Int) ^ 2) := by {
    rw [OSO.comp_pow, det]
    ring
  }
  have h_det_val : det (pow (comp p q) (n + 1)) = (-(q : Int)) ^ (n + 1) := by {
    rw [OSO.det_comp_pow]
  }
  have h_eq : (q : Int) * ((L p q (n + 2) : Int) * (L p q n : Int) - (L p q (n + 1) : Int) ^ 2) = (-(q : Int)) ^ (n + 1) := by {
    rw [h_det_form, h_det_val]
  }
  have h_rhs : (-(q : Int)) ^ (n + 1) = -(q : Int) * (-(q : Int)) ^ n := by {
    simp [Int.pow_succ]
  }
  have h_lhs : (q : Int) * ((L p q (n + 2) : Int) * (L p q n : Int) - (L p q (n + 1) : Int) ^ 2) = -(q : Int) * ((L p q (n + 1) : Int) ^ 2 - L p q (n + 2) * L p q n) := by {
    ring
  }
  have h_main : -(q : Int) * ((L p q (n + 1) : Int) ^ 2 - L p q (n + 2) * L p q n) = -(q : Int) * (-(q : Int)) ^ n := by {
    rw [h_lhs, h_eq, h_rhs]
  }
  have h_nonzero : -(q : Int) ≠ 0 := by { cases q; omega }
  exact mul_left_cancel₀ h_nonzero h_main

:= by {
  have h_pow_det : ∀ (M : M2) (n : Nat), det (pow M n) = (det M) ^ n := by {
    intro M, induction n with
    | zero => simp only [pow, one],
    | succ n ih => {
        dsimp only [pow, det, mul],
        ring,
        rw [ih],
        rw [← pow_succ'],
        ring,
      },
  },
  have h₀ : det (comp p q) = -(q : Int) := by { dsimp only [comp, det], ring },
  rw [h_pow_det, h₀],
  rfl,
}

:= by {
  have h_det_mul : ∀ x y : M2, det (mul x y) = det x * det y := by {
    intro x y, dsimp only [det, mul], ring
  },
  have h_pow_det : ∀ (M : M2) (n : Nat), det (pow M n) = (det M) ^ n := by {
    intro M, induction n with
    | zero => simp only [pow, one, det]; ring
    | succ n ih => {
        dsimp only [M2.pow],
        rw h_det_mul,
        rw ih,
        rw [← pow_succ],
      },
  },
  have h₀ : det (comp p q) = -(q : Int) := by {
    dsimp only [comp, det], ring
  },
  rw [h_pow_det, h₀],
}

:= by {
  have h_det_mul : ∀ (x y : M2), det (mul x y) = det x * det y := by {
    intro x y
    simp only [det, mul]
    ring
  }
  have h_pow_det : ∀ (M : M2) (n : Nat), det (pow M n) = (det M) ^ n := by {
    intro M
    induction n with
    | zero => simp only [pow, one, det] <;> ring
    | succ n ih =>
        dsimp only [pow]
        rw [h_det_mul]
        rw [ih]
        ring
  }
  have h₀ : det (comp p q) = -(q : Int) := by {
    simp only [comp, det] <;> ring
  }
  rw [h_pow_det, h₀]
